      "description": "Core: on: workers add changelog lines under `## [Unreleased]` and never change the version; the reviewer, once per batch after merging, moves them into a new version section, bumps the version files (patch by default; minor or major when a PR asks with the handover `release` field or a flow:minor / flow:major label) and commits \"Release x.y.z\". off: nothing changes.",
      "default": "off",
      "options": [
        "on",
        "off"
      ]
    },
    "changelog_file": {
      "type": "string",
      "title": "Changelog file",
      "description": "Advanced: The changelog (Keep a Changelog style) the release cuts.",
      "default": "CHANGELOG.md"
    },
    "cleanup": {
      "type": "string",
      "title": "Cleanup",
      "description": "Advanced: auto: after each PR the reviewer merges, and when the reviewer ends, remove worktrees and local branches of finished work that are clean and on the base or in a merged PR. off: only /flow clean. Uncommitted, unpushed, locked and live work is never removed.",
      "default": "auto",
      "options": [
        "auto",
        "off"
      ]
    },
    "worker_harness": {
      "type": "string",
      "title": "Worker harness",
      "description": "Advanced: What managers start workers with: agent (a flow:worker in this session), or a harness run in a terminal: claude, codex, gemini, opencode, or a name from the harnesses setting. Managers can still pick another one per worker.",
      "default": "agent"
    },
    "session_host": {
      "type": "string",
      "title": "Session host",
      "description": "Advanced: Where workers in other harnesses run: auto (Orca when it is running, else tmux), orca or tmux.",
      "default": "auto",
      "options": [
        "auto",
        "orca",
        "tmux"
      ]
    },
    "harnesses": {
      "type": "string",
      "title": "Harnesses",
      "description": "Advanced: JSON object of harness name to a start command line, or to {start, resume?, program?, quota?, digest?}, over the built-ins, e.g. {\"aider\": {\"start\": \"aider --yes-always --message-file {prompt_file}\", \"resume\": \"aider --restore-chat-history\"}}. {prompt} is the prompt as one shell word, {prompt_file} its path; quota is a shell command printing a percent left; digest is codex-rollout or claude-transcript; \"\" removes a built-in.",
      "default": ""
    },
    "min_quota": {
      "type": "number",
      "title": "Minimum harness quota",
      "description": "Advanced: A session worker whose harness reports its quota (codex built in, or a harness with a quota command) is refused, and the manager starts an agent worker instead, when less than this percent is left. 0: never refused.",
      "default": 10
    },
    "base_branch": {
      "type": "string",
      "title": "Base branch",
      "description": "Advanced: Branch PRs target and the reviewer pushes to. Empty: the remote's default branch.",
      "default": ""
    }
  }
}

files.types/index.d.ts:
// The cost ledger (hooks/cost.ts): tokens of one agent on one model. `long` counts the steps whose
// prompt passed the model's long-prompt threshold (they are also in the main counts).
export type Tokens = { input: number; write5m: number; write1h: number; read: number; output: number }
export type Bucket = Tokens & { long?: Tokens }
export type Role = 'manager' | 'worker' | 'reviewer' | 'main' | 'other'
export type LedgerEntry = {
  role: Role
  name: string
  // The manager a worker belongs to (the parent's name).
  manager?: string
  // `flow/<worker name>`, or the branch a continuation carries on.
  branch?: string
  spawnModel?: string
  // The worker's brief size (small/normal/large) once model routing applied one; unset otherwise.
  size?: string
  // When the agent was first and last counted (ms); the status block and the 90-day prune use them.
  firstAt?: number
  lastAt?: number
  // Completed turns (wake-ups); rows from before the counter read as 0.
  turns?: number
  models: Record<string, Bucket>
}
export type Ledger = Record<string, LedgerEntry>

// Where a harness logs what it does: Codex's rollout files, or a Claude Code transcript.
export type DigestKind = 'codex-rollout' | 'claude-transcript'

// What a worker in another harness last did, read from the harness's own log.
export type Digest = {
  // The last three tool calls, oldest first: "exec: npm test", "Edit: src/app.ts".
  actions: string[]
  lastWords?: string
  // When the log last moved, and when its last turn ended (only while no newer turn started).
  at?: number
  turnDone?: number
  tokens?: number
  window?: number
}

// One quota window as the pane draws it: how much is used, when it resets, how long it is.
export type Limit = { tool: string; label: string; used: number; resetsAt?: number; windowMs?: number }

// One agent of this session as the board shows it: the roster row from
// $.agent.list(), plus what the mod saw it do.
export type AgentRow = {
  id: string
  name?: string
  description: string
  type: string
  status: string
  parentId?: string
}

export type Activity = {
  startedAt: number
  lastAt: number
  // The newest last, at most LOG_MAX lines: "Edit src/app.ts", "Bash npm test".
  log: string[]
  // The newest call in a few plain words for the card: "running tests", "editing app.ts".
  doing?: string
  // The last turn's final text: a worker's report, or the question it ended on.
  answer?: string
  // The latest turn.step's context fill; absent until the agent has taken one.
  // The window the agent was started with, from its model; absent when unknown or before this was recorded.
  spawnWindow?: number
  usage?: { tokens: number; model: string; window?: number }
  // When the roster first saw the agent ended; its running time stops there.
  endedAt?: number
  // When the plugin told this agent to hand off; once per agent.
  handoffNotifiedAt?: number
  // The context percent when it was told, and how many wrap-up reminders rode on its tool results since.
  handoffPercent?: number
  remindersSent?: number
  // Reminder bookkeeping: tool calls since the threshold, and the percent at the last reminder.
  callsPastLimit?: number
  remindedPercent?: number
}

// A PR a manager handed to the reviewer (the handover tool), and what the reviewer did with it.
export type Handover = {
  pr: number
  title: string
  head: string
  branch: string
  reportTo: string
  verified: string
  pending: string
  afterDeploy: string
  // A command the reviewer runs to close a needs-a-person check itself.
  verifyCommand?: string
  // Parsed from the PR's ## Verification section at handover; absent in handovers saved before it existed.
  evidence?: { ran: string[]; exercised: string; notVerified: string[] }
  // 'ready': built into a batch that awaits the user's /flow push (push_mode confirm).
  status: 'pending' | 'awaiting' | 'taken' | 'ready' | 'done' | 'returned'
  // Set by the handover tool; the PR's flow:* label and the merge_mode setting are checked too.
  mode?: 'auto' | 'confirm'
  // The head the user approved with /flow approve; the reviewer merges a confirm PR only at this head.
  approvedHead?: string
  // How far the release at merge bumps for this PR; absent (old handovers) means patch.
  release?: 'patch' | 'minor' | 'major'
  // Env/secret changes the PR needs on deploy targets, from the handover tool's env field.
  env?: EnvChange[]
  at: number
  sha?: string
  report?: string
  reason?: string
}

// An open PR as `gh pr list` returns it.
export type OpenPr = {
  number: number
  title: string
  headRefName: string
  isDraft: boolean
  url: string
  updatedAt?: string
}

// The last gh listing of open flow/* PRs; `error` is the last failure, the list stays.
export type PrCache = { prs: OpenPr[]; fetchedAt: number; error?: string }

// The last dry cleanup sweep: what it would remove, and how many it keeps for a person.
export type Leftovers = { worktrees: number; branches: number; needsLook: number }

// One node of an owner's plan: a task (owner "main") or a package (owner is a manager).
export type DagState = 'waiting' | 'ready' | 'running' | 'done' | 'blocked'

export type DagNode = {
  id: string
  title: string
  // Ids of the nodes that must be done before this one starts.
  after: string[]
  // What "done" means for a dependency: its PR merged (default), or the agent reported back.
  until: 'merged' | 'reported'
  state: DagState
  // Why the node is in its state: "merged abc123", "PR returned: reason".
  info?: string
  // Set by the owner by hand; wins over what the plugin sees.
  manual?: 'done' | 'blocked'
  // The owner was already told this node is ready / blocked.
  readyNotified?: boolean
  blockedNotified?: boolean
}
// A holder of, or a waiter for, a test slot (the test_slot tool). key is the agent id, or "main".
export type SlotEntry = { key: string; name: string; label: string; since: number; claimed?: boolean }
// claimed is false for a holder granted the slot from the line who has not yet confirmed with acquire.

export type TestSlots = { holders: SlotEntry[]; waiters: SlotEntry[] }

// One line of the state dir's log.jsonl. `handoff` and `continue` are defined for a later package.
// Where a worker stood when it handed off; the successor reads it.
export type HandoffRecord = {
  branch: string
  agent: string
  agentId: string
  owner: string
  at: number
  digestPath?: string
  worktree?: string
  head?: string
  // Handoffs of this branch so far, this one included.
  count: number
  // The successor that was given this worktree; a second spawn for the branch does not get it.
  takenBy?: string
}

// A worker running outside this session: another harness in an Orca terminal or a tmux session
// (the session tool). It reports by writing `report`; the plugin sends that to its owner.
export type Session = {
  name: string
  harness: string
  host: 'orca' | 'tmux'
  // The tmux session name, or the Orca terminal handle.
  handle: string
  worktree: string
  branch: string
  // The prompt the harness started with and the file it reports into, outside any worktree.
  promptFile: string
  reportFile: string
  // The harness's command line that continues its last conversation, for "restart"; else the start line again.
  resume?: string
  start: string
  // The manager that started it: its agent id ("main" for the main session) and name.
  owner: string
  ownerName: string
  // idle: its screen stopped changing with no new report, so it may be asking something.
  status: 'running' | 'reported' | 'idle' | 'exited' | 'stopped'
  startedAt: number
  // The report file's mtime when it was last delivered.
  reportAt?: number
  // When the terminal was last seen alive.
  checkedAt?: number
  // The screen's fingerprint, when it last changed, and when it was last looked at.
  screen?: string
  screenAt?: number
  lookedAt?: number
  // The last screen itself (its last lines), for the pane.
  screenText?: string
  // The quiet spell already told to the manager as idle: "turn:<ended at>" or "quiet:<since>".
  idleKey?: string
  // Where the harness logs what it does, the file found for this session, and what it said.
  digestKind?: DigestKind
  digestFile?: string
  digestSeen?: number
  digest?: Digest
}

export type LogEvent = {
  ts: string
  event: 'spawn' | 'report' | 'handover' | 'take' | 'done' | 'back' | 'approve' | 'hold' | 'handoff' | 'continue' | 'note' | 'clean' | 'auto-answer' | 'fyi' | 'ready' | 'push' | 'main-ff'
  // The manager that owns the work, or "main".
  owner: string
  agent?: string
  pr?: number
  branch?: string
  text?: string
}

export type Question = {
  id: string
  // A decision filed before decisions had their own ids keeps its old question id here; every lookup accepts it.
  alias?: string
  // Absent: a question. 'fyi': a decision the agent took itself (question = the decision, context = why); non-blocking, undoable. Id d<N>.
  // 'deploy' asks the user to approve one deploy target at one sha; standing answers never answer it
  // (unless a rule names the kind), and no agent waits for the reply.
  // 'env' asks the user about one env/secret change on a deploy target (or a step they do themselves);
  // like 'deploy', only a rule that names the kind answers it.
  // 'push' asks the user to push one ready batch (hooks/pushgate.ts); standing answers never answer it.
  kind?: 'question' | 'fyi' | 'deploy' | 'env' | 'push'
  // Only on kind 'env': which part of an env change this item is. 'change' asks to set NAME=value, 'secret' asks
  // the user to set a secret themselves, 'login' is a step they do first, 'apply' asks them to apply an approved
  // value themselves (the target has no env_command). Never carries a secret value (there is none).
  env?: { role: 'change' | 'secret' | 'login' | 'apply'; target: string; name: string; pr: number }
  // The asking agent's name, and who answers: a worker's manager, or "main" for a manager.
  owner: string
  addressee: string
  question: string
  options: string[]
  default: string
  blocking: boolean
  context?: string
  topic?: string
  askedAt: number
  state: 'open' | 'answered'
  answer?: string
  answeredBy?: string
  answeredAt?: number
  // The answer reached the asker (or needed no message).
  delivered: boolean
  // The asker's agent id, to message it.
  askerId?: string
  // The asker is a manager: its notes get the progress and decision lines, else its manager's.
  askerIsManager?: boolean
  // The standing answer rule that answered it (answeredBy is then "standing answer").
  rule?: string
  // A guard_tests suggestion (guardtests.ts): answering "Add it" writes this mapping to the personal config.
  guard?: { glob: string; test: string }
  // An escalate standing rule holds it for the user: it is blocking and only main may answer it.
  escalated?: string
}

// next: the counter of question ids (q1 ...); nextD: the one of decisions (d1 ...), separate so the two never collide.
export type Inbox = { next: number; nextD?: number; items: Question[] }

// A person check: see hooks/checks.ts.
export type FollowUp = { state: 'open' | 'started'; manager?: string }

export type Check = {
  id: string
  kind: 'check'
  pr: number
  title: string
  steps: string
  // The plugin version that must be installed to do the check.
  version?: string
  sha?: string
  // A command the reviewer runs instead of the user (from the handover's verify_command).
  verifyCommand?: string
  createdAt: number
  state: 'open' | 'passed' | 'failed' | 'skipped'
  closedAt?: number
  closedBy?: string
  // Required for a failed check; on an open check, why scripted verification was skipped.
  note?: string
  // Only a failed check has one: work for main to start a manager on.
  followUp?: FollowUp
}

export type Checks = {
  next: number
  items: Check[]
  // The installed version main was last prompted for after an update.
  promptedVersion?: string
}

// One env change a PR needs on a deploy target. A secret has no value: the user sets it themselves.
export type EnvChange = {
  target: string
  name: string
  value?: string
  secret?: true
  why: string
  login?: string
  // The inbox items that ask about it (the change itself, and the user's own login step).
  qid: string
  loginQid?: string
}
export type EnvDone = { pr: number; name: string; how: 'command' | 'user' | 'secret' | 'dropped' | 'superseded'; at: number }

// Deploy gates (hooks/deploy.ts), kept in <state dir>/deploys.json.
export type DeployMode = 'auto' | 'confirm'
export type Hold = { until: 'batch' | 'released'; by: string; at: number; reason?: string }
// The inbox item that asks for a deploy, and the one sha it approves.
export type Approval = { qid: string; sha: string; state: 'pending' | 'approved'; at: number }
export type TargetState = {
  deployedSha?: string
  deployedAt?: number
  hold?: Hold
  approval?: Approval
  // A deploy-only run has work here: set by an approved deploy, or by releasing a hold on an auto
  // target; cleared when the target is deployed.
  due?: boolean
  // Env changes no longer pending for this target, and how (never a value).
  envDone?: EnvDone[]
}
export type Deploys = { targets: Record<string, TargetState> }

// The push gate (hooks/pushgate.ts), kept in <state dir>/push.json: the batch the reviewer built and checked and
// the user has not pushed yet. 'ready' awaits the user; 'pushing' is released (a reviewer pushes it); 'rebuilding'
// needs a fresh build (a PR was sent back, or the base moved).
export type BatchItem = { pr: number; title: string; branch: string; head: string; evidence: string }
export type ReadyBatch = {
  id: string
  state: 'ready' | 'pushing' | 'rebuilding'
  prs: number[]
  items: BatchItem[]
  sha: string
  baseSha: string
  ref: string
  check: string
  version?: string
  createdAt: number
  // The open inbox item (kind 'push') that asks the user, while state is 'ready'.
  qid?: string
  releasedAt?: number
  // Why a rebuild was asked for.
  reason?: string
}
export type PushState = { batch?: ReadyBatch }

export type Filing = {
  summary: string
  workers?: number
  criteria: string[]
  shipped: Array<{ what: string; ref: string }>
  depends: Array<{ on: string; why: string }>
}

export type Entry = {
  // The manager's latest agent name (a successor is `<name>-2`); the entry is keyed by noteKey.
  name: string
  phase: 'recon' | 'filed' | 'skipped'
  // The round it was spawned into (0: none, e.g. it filed without having been recorded at spawn).
  round: number
  spawnedAt: number
  filedAt?: number
  filing?: Filing
  // Ids of the blocking questions of the filing: it is released when none of them is open.
  blocking: string[]
  // Ids of all the questions of the filing.
  asked: string[]
}

export type Round = {
  id: number
  openedAt: number
  members: string[]
  delivered: boolean
  deliveredAt?: number
  // The members the delivered message covered; a later filing is sent on its own.
  reported: string[]
}

export type Preflight = { next: number; entries: Record<string, Entry>; rounds: Round[] }

declare module 'claude-code' {
  interface PluginState {
    'flow': {
      roster: AgentRow[]
      activity: Record<string, Activity>
      selected: string | null
      cursor: string | null
      folded: Record<string, boolean>
      now: number
      handovers: Record<string, Handover>
      // The last status and answer seen per agent name (the plan's AgentFact in hooks/dag.ts).
      'seen-agents': Record<string, { id?: string; name?: string; status: string; answer?: string; children?: number; at?: number; childAt?: number }>
      // The decision inbox, mirrored from <state dir>/inbox.json.
      inbox: Inbox
      // Person checks, mirrored from <state dir>/checks.json.
      checks: Checks
      // Tokens spent per agent and model, mirrored from <state dir>/ledger.json (hooks/cost.ts).
      ledger: Ledger
      queueRuns: number
      // Per reviewer run (agent id), what it did with the queue; persisted so a reload keeps the final report whole.
      reviewerWork: Record<string, { touched: boolean; ready: boolean; line?: string }>
      prCache: PrCache
      // Deploy gates, mirrored from <state dir>/deploys.json, and how many commits each target is behind the base.
      deploys: Deploys
      behind: Record<string, number>
      // The ready batch awaiting the user's push, mirrored from <state dir>/push.json.
      push: PushState
      // Per owner ("main" or a manager's name), the plan's nodes by id.
      plan: Record<string, Record<string, DagNode>>
      testSlots: TestSlots
      viewMode: 'tree' | 'graph' | 'inbox'
      inboxCursor: string | null
      inboxDraft: string
      inboxNote: string
      graphFocus: string | null
      overrideView: string | null | undefined
      hinted: boolean
      handoffs: Record<string, HandoffRecord>
      preflight: Preflight
      leftovers: Leftovers
      sessions: Record<string, Session>
      // Quota windows of the harnesses flow can read (Codex's own logs), for the pane.
      harnessLimits: Limit[]
      // A control pressed once that needs a second press: "<session>:<action>", and when.
      armed: { key: string; at: number } | null
      forwarded: { keys: Record<string, string[]>; lines: Record<string, string[]> }
    }
  }
}
